<body>
  <div class="card">
    <h1>
      <span>🔐</span> ShieldShare
    </h1>
    <div class="subhead">Upload a file → set a password → share the link.<br>Only people with the password can download.</div>

    <!-- UPLOAD SECTION -->
    <div id="uploadSection">
      <label class="label">1. choose file</label>
      <div class="file-upload-wrapper">
        <input type="file" id="fileInput" aria-label="File to share">
      </div>

      <label class="label">2. create a password</label>
      <div class="password-area">
        <input type="password" id="setPassword" placeholder="Password for download" autocomplete="new-password">
      </div>

      <button class="btn" id="uploadBtn" style="width:100%;">
        <span>✨</span> Generate share link
      </button>
      <div id="uploadStatus" class="status-msg" style="min-height: 1.8rem;"></div>
    </div>

    <!-- SHARE PANEL (hidden initially) -->
    <div id="sharePanel" class="share-panel hidden">
      <div class="flex-between" style="margin-bottom: 10px;">
        <span class="label" style="margin-bottom:0;">✅ file ready to share</span>
        <span class="badge" id="fileMeta">—</span>
      </div>
      <div class="share-link-box">
        <input type="text" id="shareLinkInput" readonly placeholder="Link will appear here">
        <button class="btn btn-secondary" id="copyLinkBtn" style="padding:0.8rem 1.5rem;">Copy</button>
      </div>
      <div id="copyStatus" class="status-msg" style="min-height: 1.6rem;"></div>
      <div class="divider"></div>
      <button class="btn btn-secondary" id="newUploadBtn" style="width:100%; font-size:0.85rem;">
        ⬆️ Upload another file
      </button>
    </div>

    <!-- DOWNLOAD SECTION (simulates the receiver side) -->
    <div id="downloadSection" class="download-section" style="margin-top: 1.8rem;">
      <div class="label">🔓 download area (password required)</div>
      <div id="downloadFileInfo" class="download-hint">
        No file loaded. Paste a share link or upload a file to begin.
      </div>

      <div id="passwordCheckArea">
        <div class="password-check-row">
          <input type="password" id="downloadPassword" placeholder="Enter password" autocomplete="off">
          <button class="btn" id="verifyBtn" style="padding:0.8rem 1.8rem;">Verify</button>
        </div>
        <div id="downloadStatus" class="status-msg" style="min-height: 1.8rem;"></div>
      </div>

      <button class="btn download-btn hidden" id="downloadBtn">
        ⬇️ Download file
      </button>
    </div>

    <div class="small-note">
      ⚡ files are stored in your browser · no server needed · link works on this device
    </div>
  </div>

  <script>
    (function() {
      // ----- state management -----
      let currentFile = null;           // file content as blob (or File object)
      let currentFilename = '';
      let currentPassword = '';         // stored plain (simulated)
      let currentShareId = null;        // unique id for link

      // DOM elements
      const uploadSection = document.getElementById('uploadSection');
      const sharePanel = document.getElementById('sharePanel');
      const fileInput = document.getElementById('fileInput');
      const setPasswordInput = document.getElementById('setPassword');
      const uploadBtn = document.getElementById('uploadBtn');
      const uploadStatus = document.getElementById('uploadStatus');

      const shareLinkInput = document.getElementById('shareLinkInput');
      const copyLinkBtn = document.getElementById('copyLinkBtn');
      const copyStatus = document.getElementById('copyStatus');
      const newUploadBtn = document.getElementById('newUploadBtn');
      const fileMeta = document.getElementById('fileMeta');

      const downloadFileInfo = document.getElementById('downloadFileInfo');
      const downloadPasswordInput = document.getElementById('downloadPassword');
      const verifyBtn = document.getElementById('verifyBtn');
      const downloadStatus = document.getElementById('downloadStatus');
      const downloadBtn = document.getElementById('downloadBtn');

      // ----- helper: update download area with current file info -----
      function updateDownloadHint() {
        if (currentFile && currentFilename) {
          downloadFileInfo.textContent = `📎 ${currentFilename} · password protected`;
        } else {
          downloadFileInfo.textContent = 'No file loaded. Upload a file first.';
        }
      }

      // ----- helper: generate a random id for the share link -----
      function generateShareId() {
        return 'f' + Math.random().toString(36).substring(2, 12) + Date.now().toString(36).slice(-6);
      }

      // ----- reset download UI (hide download button, clear password) -----
      function resetDownloadUI() {
        downloadBtn.classList.add('hidden');
        downloadPasswordInput.value = '';
        downloadStatus.textContent = '';
        downloadStatus.classList.remove('error');
      }

      // ----- build shareable link based on current file & password -----
      function buildShareLink() {
        if (!currentFile || !currentShareId) return '';
        // In a real app this would be a server URL. Here we encode the data into a pseudo-link.
        // For the demo, we use the shareId to identify the file in the current session.
        // The link also embeds the filename (base64, no password) to show info.
        const base = window.location.href.split('?')[0].split('#')[0];
        const fileNameEncoded = encodeURIComponent(currentFilename);
        return `${base}?share=${currentShareId}&name=${fileNameEncoded}`;
      }

      // ----- update share panel with current link + metadata -----
      function updateSharePanel() {
        if (!currentFile) {
          sharePanel.classList.add('hidden');
          return;
        }
        sharePanel.classList.remove('hidden');
        const link = buildShareLink();
        shareLinkInput.value = link;
        // show file size / name
        const sizeKB = (currentFile.size / 1024).toFixed(1);
        fileMeta.textContent = `${currentFilename} · ${sizeKB} KB`;
        // clear copy status
        copyStatus.textContent = '';
      }

      // ----- reset entire upload state (new upload) -----
      function resetUploadState() {
        currentFile = null;
        currentFilename = '';
        currentPassword = '';
        currentShareId = null;
        fileInput.value = '';
        setPasswordInput.value = '';
        uploadStatus.textContent = '';
        uploadStatus.classList.remove('error');
        sharePanel.classList.add('hidden');
        resetDownloadUI();
        downloadFileInfo.textContent = 'No file loaded. Upload a file first.';
        // do NOT clear download password input automatically (fine)
      }

      // ----- handle file selection: only preview metadata, no upload yet -----
      fileInput.addEventListener('change', function(e) {
        const file = e.target.files[0];
        if (file) {
          // just show a hint that file is selected
          uploadStatus.textContent = `📄 ${file.name} selected · set a password and click generate`;
          uploadStatus.classList.remove('error');
        } else {
          uploadStatus.textContent = '';
        }
      });

      // ----- upload & create share link -----
      uploadBtn.addEventListener('click', function() {
        const file = fileInput.files[0];
        const password = setPasswordInput.value.trim();

        // validation
        if (!file) {
          uploadStatus.textContent = '❌ Please choose a file first.';
          uploadStatus.classList.add('error');
          return;
        }
        if (!password) {
          uploadStatus.textContent = '❌ Please set a password.';
          uploadStatus.classList.add('error');
          return;
        }

        // store file & password in memory
        currentFile = file;                   // File object (blob)
        currentFilename = file.name;
        currentPassword = password;
        currentShareId = generateShareId();

        // clear any previous download status
        resetDownloadUI();

        // show success message
        uploadStatus.textContent = `✅ File "${file.name}" ready! Share the link below.`;
        uploadStatus.classList.remove('error');

        // update download hint with file info
        updateDownloadHint();

        // show share panel with link
        updateSharePanel();

        // hide upload section? not necessary, but user might want to upload another.
        // we keep upload section visible, but we also show share panel.
        // good.
      });

      // ----- copy link to clipboard -----
      copyLinkBtn.addEventListener('click', function() {
        if (!shareLinkInput.value) return;
        shareLinkInput.select();
        shareLinkInput.setSelectionRange(0, 99999);
        navigator.clipboard.writeText(shareLinkInput.value).then(() => {
          copyStatus.textContent = '📋 Link copied to clipboard!';
          copyStatus.classList.remove('error');
          setTimeout(() => { copyStatus.textContent = ''; }, 2500);
        }).catch(() => {
          copyStatus.textContent = '❌ Could not copy. Please select and copy manually.';
          copyStatus.classList.add('error');
        });
      });

      // ----- new upload: reset everything -----
      newUploadBtn.addEventListener('click', function() {
        resetUploadState();
        // also reset file input and password fields
        fileInput.value = '';
        setPasswordInput.value = '';
        uploadStatus.textContent = '';
        downloadStatus.textContent = '';
        downloadPasswordInput.value = '';
        downloadBtn.classList.add('hidden');
        downloadFileInfo.textContent = 'No file loaded. Upload a file first.';
        // scroll to top of card
        document.querySelector('.card').scrollIntoView({ behavior: 'smooth', block: 'start' });
      });

      // ----- verify password for download -----
      verifyBtn.addEventListener('click', function() {
        const enteredPassword = downloadPasswordInput.value.trim();

        if (!currentFile || !currentPassword) {
          downloadStatus.textContent = '⚠️ No file to download. Upload a file first.';
          downloadStatus.classList.add('error');
          downloadBtn.classList.add('hidden');
          return;
        }

        if (!enteredPassword) {
          downloadStatus.textContent = '❌ Please enter the password.';
          downloadStatus.classList.add('error');
          downloadBtn.classList.add('hidden');
          return;
        }

        if (enteredPassword === currentPassword) {
          downloadStatus.textContent = '✅ Correct password! You can now download.';
          downloadStatus.classList.remove('error');
          downloadBtn.classList.remove('hidden');
        } else {
          downloadStatus.textContent = '❌ Incorrect password. Try again.';
          downloadStatus.classList.add('error');
          downloadBtn.classList.add('hidden');
        }
      });

      // ----- download file (trigger blob download) -----
      downloadBtn.addEventListener('click', function() {
        if (!currentFile) {
          downloadStatus.textContent = '⚠️ No file available.';
          downloadStatus.classList.add('error');
          return;
        }

        // Create a download link using blob URL
        const blob = currentFile.slice(0, currentFile.size, currentFile.type);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = currentFilename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        // optional feedback
        downloadStatus.textContent = '📥 Download started.';
        downloadStatus.classList.remove('error');
        setTimeout(() => {
          if (downloadStatus.textContent === '📥 Download started.') {
            downloadStatus.textContent = '✅ Correct password! You can now download.';
          }
        }, 2000);
      });

      // ----- handle page load: if share link present, show that file? (simulated) -----
      // For the demo we only use in-session files. But we could parse the share parameter
      // and if it matches our current file, show info. But since it's all in-browser, we ignore.
      // However, we do want to make it easy to simulate "opening a link".
      // Instead, we can add a hint: when a user clicks the generated link, they'd see the download area pre-filled.
      // Since it's a single page app, we can's easily parse it without state. We'll leave it as a clean demo.

      // extra: when generating link, you can also manually test by clicking verify.
      // To make it a bit more tangible, we prefill download password input with nothing.

      // reset any initial UI
      resetUploadState();

      // if there's a '?share=' param we could populate (but we can't recover file). This demo
      // only works for the uploader. Sharing across devices isn't supported because it's client-side.
      // That's fine — we note it in the footnote.

      // final safety: clear download button when password field changes (prevent accidental download w/o verify)
      downloadPasswordInput.addEventListener('input', function() {
        // hide download button if they modify password after verification
        downloadBtn.classList.add('hidden');
        // don't clear status if it's already an error? we can clear success
        if (downloadStatus.textContent.includes('Correct password')) {
          downloadStatus.textContent = '';
        }
      });

      // also clear download button when file changes
      // already handled by resetUploadState/updateDownloadHint

    })();
  </script>
</body>
</html>
